const { retry } = require('acme-retry');

// A "flaky" function that fails randomly but succeeds after a few tries
async function flakyFunction() {
  const random = Math.random();
  console.log(`Attempting... random value: ${random.toFixed(4)}`);

  if (random < 0.7) {
    throw new Error('Flaky function failed!');
  }

  return 'Success!';
}

async function main() {
  try {
    const result = await retry(flakyFunction, { 
      attempts: 5,    // Retry up to 5 times
      baseMs: 100    // Start with 100ms delay, double each time
    });
    console.log('Result:', result);
  } catch (err) {
    console.error('All attempts failed:', err.message);
  }
}

main();
```

## How it works

The `acme-retry` package exports a single `retry` function:

```javascript
await retry(fn, { attempts: 5, baseMs: 100 });
```

| Parameter | Description | Default |
|-----------|-------------|---------|
| `fn` | The function to retry (async or sync) | — |
| `opts.attempts` | Maximum number of attempts before giving up | 3 |
| `opts.baseMs` | Base delay for exponential backoff (ms) | 100 |

**Key behaviors:**
1. **Exponential backoff** — Each failed attempt waits before retrying: `baseMs * 2^i`
   - Attempt 0: no delay (first try)
   - Attempt 1: 100ms delay
   - Attempt 2: 200ms delay
   - Attempt 3: 400ms delay
   - Attempt 4: 800ms delay

2. **Returns immediately on success** — If `fn()` succeeds, the retry stops and returns the result.

3. **Throws on final failure** — If all attempts fail, it throws the last error.

The example demonstrates a function that succeeds ~30% of the time. With 5 attempts, you'll usually see it succeed after 1-4 tries, but occasionally all 5 attempts fail (as shown in the last run above).

